def summarize(values):
    numbers = [v for v in values if v is not None]
    if not numbers:
        return {"count": 0, "sum": 0, "mean": None}
    return {"count": len(numbers), "sum": sum(numbers), "mean": sum(numbers) // len(numbers)}

